INSERT INTO plant_releases (id, plant_id, version, content_hash, data_origin, facility_id, manifest, layout) VALUES
  ('a8937811-425e-57f9-94c9-e2a231cfe554', 'waterplant', '0.1.0', '49e081ed97884538d827a22117702b1806d25dd336b2f26d63048362cc495029', 'surveyed', 'SITE-01', '{"conventions": {"flow_unit": "L/h", "pressure_note": "Dial gauges print kg/cm2 (black, 0-7) and psi (red, 0-100). 1 kg/cm2 = 14.22 psi. Readings are stored in psi.", "pressure_unit": "psi", "telemetry_mode": "SIMULATED. The real HMI/PLC brand and export were not legible in the footage.", "valve_lever_angle_deg": "0 = lever aligned with pipe (open), 90 = perpendicular (closed)"}, "data_origin": "surveyed", "facility_id": "SITE-01", "id": "waterplant", "name": "Mineral water plant, L-shaped (filmed site)", "not_modelled": ["media vessel top and bottom gauges, if any", "ozone dosing sensor", "compressed air and electrical distribution detail beyond MCC and HMI as support equipment", "the bottling line internals"], "open_questions": ["Cartridge bank micron rating: handwritten labels read ''0.2 micron'' (dated 02/09/2026); standard RO practice puts a 5 and 1 micron bank before the HP pump. Do not state a rating on screen.", "Cartridge bank wiring: modelled as 4 lines of two housings in series (front then back) with one gauge on each dome. Confirm by tracing pipes.", "Pre-filter (small cylinder) position: modelled between the media train and the cartridge bank.", "SOP numbers on the yellow-lever valves (e.g. #14, #17) are not yet mapped to V-xxx tags.", "RO vessel count and rotameter ranges."], "sections": {"L1": "Leg 1, primary corridor (tanks, RO, cartridge bank, ozone, HMI, MCC)", "L2": "Leg 2, pre-treatment and pressure wing (media train, pre-filter, HP pump)"}, "version": "0.1.0"}'::jsonb, '{"approximate": true, "floor": [[0.0, 0.0], [23.0, 0.0], [23.0, 6.0], [6.0, 6.0], [6.0, 16.0], [0.0, 16.0]], "notes": ["Cartridge bank rows: front row (z 3.6) carries the higher-pressure gauges, back row (z 2.5) the lower.", "Boundary supply and filling line are drawn outside the building outline on purpose."], "placements":